// AutoDeploy's build runner, inside the user's own GitHub Actions job (ADR 0010).
// Plain JavaScript on purpose: the workflow file embeds this text as it is
// (src/ci-runner-source.ts, generated by `pnpm --filter @autodeploy/github
// gen:ci-runner`), so no compiler can change what runs. Node 18+, nothing
// but Node's own modules, its environment and AUTODEPLOY_JOB.
//
//   1. claims the build attempt from the API and receives the project's
//      variables (masked in GitHub's log);
//   2. applies a proposed repair, then runs the install-and-build script,
//      streaming its log to the API every 2 s;
//   3. packs the checkout (no .git or caches; node_modules only as told),
//      sends it in parts, then reports the exit code.
//
// Every call carries the job's OIDC token: the API accepts it only from this
// repository's autodeploy.yml, for this attempt (the nonce), from one run.
'use strict';
const { spawn } = require('node:child_process');
const { mkdtempSync, readdirSync, readFileSync } = require('node:fs');
const { join } = require('node:path');
const { tmpdir } = require('node:os');

const env = process.env;
const job = JSON.parse(env.AUTODEPLOY_JOB || '{}');
const ws = env.GITHUB_WORKSPACE || process.cwd();
const out = (s) => process.stdout.write(`${s}\n`);
const q = (s) => `'${String(s).replace(/'/g, `'\\''`)}'`;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function jobToken() {
  const url = `${env.ACTIONS_ID_TOKEN_REQUEST_URL}&audience=${encodeURIComponent(job.api)}`;
  const r = await fetch(url, {
    headers: { authorization: `bearer ${env.ACTIONS_ID_TOKEN_REQUEST_TOKEN}` },
  });
  if (!r.ok)
    throw new Error(`no GitHub job token (${r.status}): the workflow needs id-token: write`);
  return (await r.json()).value;
}

async function call(method, path, body, binary) {
  for (let attempt = 1; ; attempt++) {
    let fatal = null;
    try {
      const r = await fetch(`${job.api}/ci/v1/${path}`, {
        method,
        headers: {
          authorization: `Bearer ${await jobToken()}`,
          'x-autodeploy-attempt': job.attemptId,
          'x-autodeploy-nonce': job.nonce,
          'content-type': binary ? 'application/octet-stream' : 'application/json',
        },
        body: binary ? body : JSON.stringify(body || {}),
      });
      if (r.ok) return r.status === 204 ? null : r.json();
      const detail = await r.text();
      // 4xx: AutoDeploy said no (wrong repository, too big, already finished…).
      if (r.status < 500) fatal = new Error(`AutoDeploy refused ${path}: ${r.status} ${detail}`);
      else if (attempt >= 4) fatal = new Error(`AutoDeploy failed ${path}: ${r.status} ${detail}`);
    } catch (err) {
      if (attempt >= 4) fatal = err;
    }
    if (fatal) throw fatal;
    await sleep(attempt * 2000);
  }
}

async function main() {
  // 1. Claim the attempt; the project's variables are masked from here on.
  const start = await call('POST', 'start', {});
  const secrets = start?.env || {};
  for (const v of Object.values(secrets))
    for (const line of String(v).split('\n')) if (line.trim()) out(`::add-mask::${line}`);
  out(`::add-mask::${job.nonce}`);

  // 2. The log, sent in batches.
  let pending = [];
  let sent = Promise.resolve();
  let count = 0;
  const flush = () => {
    if (pending.length === 0) return sent;
    const lines = pending;
    pending = [];
    sent = sent
      .then(() => call('POST', 'log', { lines }))
      .catch((e) => out(`::warning::AutoDeploy did not get some log lines: ${e.message}`));
    return sent;
  };
  const timer = setInterval(flush, 2000);
  const emit = (line) => {
    out(line);
    if (count++ < 100000) pending.push(line.slice(0, 4000));
    if (pending.length >= 500) flush();
  };
  // The build sees the project's variables, never the job's token or nonce.
  const buildEnv = { ...env, ...job.env, ...secrets, CI: '1' };
  delete buildEnv.ACTIONS_ID_TOKEN_REQUEST_TOKEN;
  delete buildEnv.ACTIONS_ID_TOKEN_REQUEST_URL;
  delete buildEnv.AUTODEPLOY_JOB;
  const run = (cmd, input) =>
    new Promise((resolve) => {
      const p = spawn('bash', ['-c', cmd], {
        cwd: ws,
        env: buildEnv,
        stdio: [input === undefined ? 'ignore' : 'pipe', 'pipe', 'pipe'],
      });
      for (const s of [p.stdout, p.stderr]) {
        let buf = '';
        s.on('data', (d) => {
          buf += d.toString();
          const lines = buf.split('\n');
          buf = lines.pop();
          for (const l of lines) emit(l);
        });
        s.on('end', () => {
          if (buf) emit(buf);
        });
      }
      if (input !== undefined) p.stdin.end(input);
      p.on('close', (code) => resolve(code === null ? 1 : code));
    });

  let exitCode = 0;
  let parts = 0;
  let bytes = 0;
  try {
    if (job.patch) {
      emit('▸ applying the proposed repair');
      const patch = job.patch.endsWith('\n') ? job.patch : `${job.patch}\n`;
      exitCode = await run(
        `cd ${q(job.root || '.')} && git apply --whitespace=nowarn --recount -`,
        patch,
      );
      if (exitCode !== 0) emit('autodeploy: the proposed patch did not apply cleanly');
    }
    if (exitCode === 0) exitCode = await run(`corepack enable 2>/dev/null || true\n${job.script}`);

    // 3. The checkout as built: no .git or caches; node_modules as told.
    if (exitCode === 0) {
      emit('▸ sending the build to AutoDeploy');
      const dir = mkdtempSync(join(tmpdir(), 'autodeploy-'));
      const prune = [
        '-path ./.git',
        '-name .cache',
        '-name .turbo',
        "-path '*/.next/cache'",
        "-path '*/node_modules/.cache'",
      ];
      if (job.keep.deps === 'none') prune.push('-name node_modules');
      if (job.keep.deps === 'under')
        prune.push(`\\( -name node_modules ! -path ${q(`./${job.keep.path}/*`)} \\)`);
      const list = q(join(dir, 'files'));
      const packed = await run(
        `find . \\( ${prune.join(' -o ')} \\) -prune -o -print0 > ${list} && ` +
          `tar --null --no-recursion -czf - -T ${list} | split -b ${job.partBytes} -a 3 - ${q(join(dir, 'part.'))}`,
      );
      if (packed !== 0) throw new Error('could not pack the build');
      const names = readdirSync(dir)
        .filter((n) => n.startsWith('part.'))
        .sort();
      for (const name of names) {
        const body = readFileSync(join(dir, name));
        await call('PUT', `parts/${parts}`, body, true);
        parts++;
        bytes += body.length;
      }
      emit(`▸ sent ${(bytes / 1048576).toFixed(1)} MB in ${parts} part${parts === 1 ? '' : 's'}`);
    }
  } catch (err) {
    emit(`autodeploy: ${err.message}`);
    if (exitCode === 0) exitCode = 1;
  } finally {
    clearInterval(timer);
    await flush();
  }
  await call('POST', 'finish', { exitCode, parts, bytes });
  process.exitCode = exitCode;
}

main().catch((err) => {
  console.error(`autodeploy: ${err.message}`);
  process.exit(1);
});
